#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: one-off Google Cloud + Neon + GitHub setup for the release pipeline
# (.github/workflows/release.yml and deploy.yml). Safe to re-run: every step
# checks before creating. Non-secret answers are remembered in .setup-gcp.env
# (git-ignored); secrets go straight to Secret Manager or GitHub, never to disk.
# ──────────────────────────────────────────────────────────────────────────
ENV_FILE=".setup-gcp.env"
REPO="Thytus777/car-crash-ai"
AR_REPO="car-crash-ai"
DEPLOY_SA_NAME="gh-deploy"
RUNTIME_SA_NAME="car-crash-ai-run"
POOL="github"
PROVIDER="github-oidc"

cd "$(git rev-parse --show-toplevel)"

# put_secret NAME VALUE: create the Secret Manager secret or add a new version.
put_secret() {
  if gcloud secrets describe "$1" --project "$GCP_PROJECT_ID" >/dev/null 2>&1; then
    printf '%s' "$2" | gcloud secrets versions add "$1" --project "$GCP_PROJECT_ID" --data-file=- >/dev/null
  else
    printf '%s' "$2" | gcloud secrets create "$1" --project "$GCP_PROJECT_ID" \
      --replication-policy=automatic --data-file=- >/dev/null
  fi
  printf '  %s✓ stored%s Secret Manager secret %s\n' "$GREEN" "$RESET" "$1"
}

# asyncpg_url URL: Neon's postgresql://...?sslmode=require&channel_binding=require
# becomes postgresql+asyncpg://...?ssl=require (asyncpg rejects the libpq options).
asyncpg_url() {
  local base="${1%%\?*}"
  base="${base/#postgresql:\/\//postgresql+asyncpg://}"
  base="${base/#postgres:\/\//postgresql+asyncpg://}"
  printf '%s?ssl=require' "$base"
}

# gh_env ENV REVIEWERS_JSON REF...: create a GitHub Environment that only the
# given branches (or tag:<pattern> tags) may deploy to.
gh_env() {
  local env="$1" reviewers="$2" ref
  shift 2
  printf '{"reviewers": %s, "deployment_branch_policy": {"protected_branches": false, "custom_branch_policies": true}}' \
    "$reviewers" | gh api -X PUT "repos/$REPO/environments/$env" --input - >/dev/null
  for ref in "$@"; do
    if [[ $ref == tag:* ]]; then
      gh api -X POST "repos/$REPO/environments/$env/deployment-branch-policies" \
        -f name="${ref#tag:}" -f type=tag >/dev/null 2>&1 || true # already exists
    else
      gh api -X POST "repos/$REPO/environments/$env/deployment-branch-policies" \
        -f name="$ref" -f type=branch >/dev/null 2>&1 || true
    fi
  done
  printf '  %s✓ environment%s %s (deploys from: %s)\n' "$GREEN" "$RESET" "$env" "$*"
}

TOTAL_STAGES=12

banner "Car Crash AI · Cloud Run deploy setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools and logins"
say "You need the Google Cloud CLI (gcloud) and the GitHub CLI (gh), both logged in."
for tool in gcloud gh openssl; do
  if command -v "$tool" >/dev/null 2>&1; then step "$tool found"; else warn "$tool not found"; fi
done
if ! command -v gcloud >/dev/null 2>&1; then
  open_url "https://cloud.google.com/sdk/docs/install"
  say "Install it, open a new terminal, and re-run this wizard."
  exit 1
fi
note "If either login below is missing, run it in another terminal first:"
note "  gcloud auth login      gh auth login"
say "gcloud account: $(gcloud auth list --filter=status:ACTIVE --format='value(account)')"
say "gh account:     $(gh api user --jq .login 2>/dev/null || echo 'not logged in')"
pause "Both logged in? Press Enter"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud project and billing"
say "Cloud Run needs a project with a billing account attached. At this app's"
say "traffic it should stay inside the free tier, but Google still requires a"
say "billing account. The next stage adds a budget alert."
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project (e.g. name 'car-crash-ai'), then copy its Project ID (not the name)."
step "Link a billing account if prompted: Billing → Link a billing account."
ask GCP_PROJECT_ID "Project ID:"
ask GCP_REGION "Region [australia-southeast1]:"
GCP_REGION="${GCP_REGION:-australia-southeast1}"
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
write_env GCP_REGION "$GCP_REGION"
gcloud config set project "$GCP_PROJECT_ID" >/dev/null
PROJECT_NUMBER="$(gcloud projects describe "$GCP_PROJECT_ID" --format='value(projectNumber)')"
step "project number: $PROJECT_NUMBER"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Budget alert"
say "A budget emails you before anything costs real money. Suggested: 5/month in"
say "your billing currency, with alerts at 50%, 90% and 100%."
open_url "https://console.cloud.google.com/billing/budgets?project=$GCP_PROJECT_ID"
step "Create budget → scope: this project → amount: 5 → keep the default thresholds → Finish."
note "A budget alerts; it doesn't cap spend. --max-instances=2 in deploy.yml bounds Cloud Run."
pause "Budget created? Press Enter"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "APIs and Artifact Registry"
say "Enables Cloud Run, Artifact Registry, Secret Manager and the IAM APIs that"
say "keyless GitHub auth needs, then creates the Docker repository '$AR_REPO'."
if confirm "Enable the APIs and create the repository in $GCP_PROJECT_ID?"; then
  gcloud services enable run.googleapis.com artifactregistry.googleapis.com \
    secretmanager.googleapis.com iam.googleapis.com iamcredentials.googleapis.com \
    sts.googleapis.com cloudresourcemanager.googleapis.com --project "$GCP_PROJECT_ID"
  gcloud artifacts repositories describe "$AR_REPO" --location "$GCP_REGION" >/dev/null 2>&1 ||
    gcloud artifacts repositories create "$AR_REPO" --repository-format=docker \
      --location "$GCP_REGION" --description "car-crash-ai images (copied from GHCR by digest)"
  step "APIs enabled, repository ready"
else
  SKIPPED+=("APIs + Artifact Registry repository")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Service accounts"
DEPLOY_SA="$DEPLOY_SA_NAME@$GCP_PROJECT_ID.iam.gserviceaccount.com"
RUNTIME_SA="$RUNTIME_SA_NAME@$GCP_PROJECT_ID.iam.gserviceaccount.com"
say "Two identities, each with only what it needs:"
step "$DEPLOY_SA_NAME: GitHub Actions pushes images, deploys, runs migrations and smoke tests"
step "$RUNTIME_SA_NAME: what the running service is; it can only read secrets"
if confirm "Create them and grant the roles?"; then
  gcloud iam service-accounts describe "$DEPLOY_SA" >/dev/null 2>&1 ||
    gcloud iam service-accounts create "$DEPLOY_SA_NAME" --display-name "GitHub Actions deployer"
  gcloud iam service-accounts describe "$RUNTIME_SA" >/dev/null 2>&1 ||
    gcloud iam service-accounts create "$RUNTIME_SA_NAME" --display-name "car-crash-ai Cloud Run runtime"
  for role in roles/run.admin roles/artifactregistry.writer roles/secretmanager.secretAccessor; do
    gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" --member "serviceAccount:$DEPLOY_SA" \
      --role "$role" --condition=None >/dev/null
  done
  gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" --member "serviceAccount:$RUNTIME_SA" \
    --role roles/secretmanager.secretAccessor --condition=None >/dev/null
  # The deployer may start revisions as the runtime account, and as nothing else.
  gcloud iam service-accounts add-iam-policy-binding "$RUNTIME_SA" \
    --member "serviceAccount:$DEPLOY_SA" --role roles/iam.serviceAccountUser >/dev/null
  step "service accounts and roles ready"
else
  SKIPPED+=("service accounts and IAM roles")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Keyless GitHub → Google auth (Workload Identity Federation)"
say "Each GitHub Actions run gets a short-lived token through OIDC; no service-account"
say "key is ever created. Only workflows in $REPO can use it."
WIF_PROVIDER="projects/$PROJECT_NUMBER/locations/global/workloadIdentityPools/$POOL/providers/$PROVIDER"
if confirm "Create the identity pool and provider?"; then
  gcloud iam workload-identity-pools describe "$POOL" --location global >/dev/null 2>&1 ||
    gcloud iam workload-identity-pools create "$POOL" --location global --display-name "GitHub Actions"
  gcloud iam workload-identity-pools providers describe "$PROVIDER" --location global \
    --workload-identity-pool "$POOL" >/dev/null 2>&1 ||
    gcloud iam workload-identity-pools providers create-oidc "$PROVIDER" --location global \
      --workload-identity-pool "$POOL" --display-name "GitHub OIDC" \
      --issuer-uri "https://token.actions.githubusercontent.com" \
      --attribute-mapping "google.subject=assertion.sub,attribute.repository=assertion.repository,attribute.ref=assertion.ref" \
      --attribute-condition "assertion.repository == '$REPO'"
  gcloud iam service-accounts add-iam-policy-binding "$DEPLOY_SA" --role roles/iam.workloadIdentityUser \
    --member "principalSet://iam.googleapis.com/projects/$PROJECT_NUMBER/locations/global/workloadIdentityPools/$POOL/attribute.repository/$REPO" \
    >/dev/null
  step "provider: $WIF_PROVIDER"
else
  SKIPPED+=("Workload Identity pool and provider")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Gemini API key"
say "The service's model key, shared by staging and production. Create a fresh"
say "key rather than reusing one that has been in local logs or chat."
open_url "https://aistudio.google.com/app/apikey"
step "Create API key → copy it."
ask_secret GEMINI_KEY "Paste the Gemini API key:"
if [[ -n "$GEMINI_KEY" ]]; then put_secret gemini-api-key "$GEMINI_KEY"; else SKIPPED+=("gemini-api-key secret"); fi
unset GEMINI_KEY
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Neon Postgres (staging + production)"
say "Neon's free plan is enough. Use one project with two branches so staging"
say "and production data never mix."
open_url "https://console.neon.tech/app/projects"
step "New project → name 'car-crash-ai' → region AWS Asia Pacific (Sydney)."
step "Branches → the default branch is production. Create a branch named 'staging'."
step "For each branch: Dashboard → Connect → pick the branch → copy the connection string."
note "The wizard converts it to the asyncpg form (postgresql+asyncpg://...?ssl=require)."
ask_secret NEON_STAGING "Paste the STAGING connection string:"
if [[ -n "$NEON_STAGING" ]]; then
  put_secret staging-database-url "$(asyncpg_url "$NEON_STAGING")"
else
  SKIPPED+=("staging-database-url secret")
fi
ask_secret NEON_PROD "Paste the PRODUCTION connection string:"
if [[ -n "$NEON_PROD" ]]; then
  put_secret production-database-url "$(asyncpg_url "$NEON_PROD")"
else
  SKIPPED+=("production-database-url secret")
fi
unset NEON_STAGING NEON_PROD
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Client API keys"
say "Production refuses to start without API keys. This generates one random key"
say "per environment straight into Secret Manager. The smoke test uses the first"
say "key in the list. Add more as comma-separated versions (docs/RUNBOOK.md)."
for env in staging production; do
  if gcloud secrets describe "$env-api-keys" >/dev/null 2>&1 && ! confirm "$env-api-keys exists. Replace it?"; then
    continue
  fi
  put_secret "$env-api-keys" "$(openssl rand -hex 32)"
done
note "Read a key when you need one:"
note "  gcloud secrets versions access latest --secret=production-api-keys"
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "GitHub environments and variables"
say "staging deploys from main. production deploys from release tags (v*) or main"
say "(manual rollback), and every production deploy waits for your approval."
ask CORS_STAGING "Allowed browser origins for staging [http://localhost:3000]:"
CORS_STAGING="${CORS_STAGING:-http://localhost:3000}"
ask CORS_PRODUCTION "Allowed browser origins for production [http://localhost:3000]:"
CORS_PRODUCTION="${CORS_PRODUCTION:-http://localhost:3000}"
write_env CORS_STAGING "$CORS_STAGING"
write_env CORS_PRODUCTION "$CORS_PRODUCTION"
ME_ID="$(gh api user --jq .id)"
gh_env staging '[]' main
gh_env production "[{\"type\":\"User\",\"id\":$ME_ID}]" main 'tag:v*'
gh variable set CLOUD_RUN_SERVICE --env staging --repo "$REPO" --body car-crash-ai-staging
gh variable set CLOUD_RUN_SERVICE --env production --repo "$REPO" --body car-crash-ai-production
gh variable set CORS_ORIGINS --env staging --repo "$REPO" --body "$CORS_STAGING"
gh variable set CORS_ORIGINS --env production --repo "$REPO" --body "$CORS_PRODUCTION"
for kv in "GCP_REGION=$GCP_REGION" "GCP_WIF_PROVIDER=$WIF_PROVIDER" "GCP_DEPLOY_SA=$DEPLOY_SA" \
          "GCP_RUNTIME_SA=$RUNTIME_SA" "GCP_AR_REPO=$AR_REPO"; do
  gh variable set "${kv%%=*}" --repo "$REPO" --body "${kv#*=}" && step "variable ${kv%%=*}"
done
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Release token for release-please"
say "release-please opens the release PR. GitHub won't let the default Actions"
say "token open it, and checks never run on PRs that token opens. A fine-grained"
say "token fixes both."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Name: car-crash-ai release-please · Expiration: 1 year"
step "Repository access: Only select repositories → $REPO"
step "Permissions → Repository: Contents = Read and write, Pull requests = Read and write"
step "Generate token → copy it."
ask_secret RP_TOKEN "Paste the token:"
if [[ -n "$RP_TOKEN" ]]; then
  set_secret RELEASE_PLEASE_TOKEN "$RP_TOKEN"
else
  SKIPPED+=("RELEASE_PLEASE_TOKEN secret")
fi
unset RP_TOKEN
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Switch deploys on"
say "Setting GCP_PROJECT_ID is what enables the deploy jobs in release.yml."
if confirm "Enable deploys now?"; then
  set_var GCP_PROJECT_ID "$GCP_PROJECT_ID"
  if confirm "Re-run the latest main build so it deploys to staging now?"; then
    run_id="$(gh run list --repo "$REPO" --workflow release.yml --branch main --event push -L 1 --json databaseId --jq '.[0].databaseId')"
    gh run rerun "$run_id" --repo "$REPO" && step "re-running release run $run_id"
    open_url "https://github.com/$REPO/actions/runs/$run_id"
  fi
else
  SKIPPED+=("gh variable set GCP_PROJECT_ID --body $GCP_PROJECT_ID (this enables deploys)")
fi
pause
# ──────────────────────────────────────────────────────────────────────────

finish
